class Solution:

	def findParent(self, root, mp, vis):
		q = []
		q.append(root)
		while q:
			curr = q.pop(0)
			vis[curr] = 0
			if curr.left:
				mp[curr.left] = curr
				q.append(curr.left)
			if curr.right:
				mp[curr.right] = curr
				q.append(curr.right)

	def ladoos(self, root, home, k):
		mp = {}
		vis = {}
		self.findParent(root, mp, vis)
		q = []
		for (node, parent) in mp.items():
			if node.data == home or parent.data == home:
				if node.data == home:
					q.append([node, 0])
					vis[node] = 1
					break
				if parent.data == home:
					q.append([parent, 0])
					vis[parent] = 1
					break
		sum = q[0][0].data
		while q:
			size = len(q)
			lvl = q[0][1]
			if lvl == k:
				break
			lvl += 1
			for i in range(size):
				(curr, curr_lvl) = q.pop(0)
				if curr.left and vis[curr.left] == 0:
					vis[curr.left] = 1
					sum += curr.left.data
					q.append([curr.left, lvl])
				if curr.right and vis[curr.right] == 0:
					vis[curr.right] = 1
					sum += curr.right.data
					q.append([curr.right, lvl])
				if mp.get(curr) and vis.get(mp[curr]) == 0:
					vis[mp[curr]] = 1
					sum += mp[curr].data
					q.append([mp[curr], lvl])
		return sum
